function r(i){const e=(i??"").toLowerCase();return e.includes("invalid login credentials")?"המייל או הסיסמה לא נכונים. אם נכנסת עד היום עם Google, הגדר סיסמה בהגדרות (בדפדפן) או לחץ 'שכחתי סיסמה'.":e.includes("email not confirmed")?"המייל עוד לא אושר. חפש את מייל האישור (גם בספאם).":e.includes("already registered")||e.includes("already been registered")?"כבר יש חשבון עם המייל הזה. התחבר, או לחץ 'שכחתי סיסמה'.":e.includes("password should be at least")||e.includes("weak password")?"הסיסמה קצרה מדי. לפחות 6 תווים.":e.includes("rate limit")||e.includes("too many")||e.includes("security purposes")?"יותר מדי ניסיונות. חכה כמה דקות ונסה שוב.":e.includes("same password")||e.includes("different from the old")?"זו כבר הסיסמה הנוכחית. בחר סיסמה אחרת.":e.includes("unable to validate email")||e.includes("invalid email")?"כתובת המייל לא תקינה.":e.includes("network")||e.includes("fetch")?"אין חיבור לאינטרנט. נסה שוב.":i||"שגיאה בהתחברות"}export{r as a};
